// DSF/DSDIFF/DST through DSD Nexus (docs/Plan.md §5.8, §16.6). Fixtures are written here from known raw DSD bytes, so
// the generated bytes are the independent reference; local real DSF files are compared against a separate parse.
#include <gtest/gtest.h>

#include <algorithm>
#include <fstream>
#include <functional>
#include <string>
#include <utility>
#include <vector>

#include "Common/AudioTypes.h"
#include "Engine/decode/DsdReader.h"
#include "TestUtil.h"

using namespace camel::audio;

namespace {

constexpr uint32_t kDsd64 = 2822400;
constexpr size_t kBlock = 4096;

using Bytes = std::vector<uint8_t>;

uint8_t reversed(uint8_t b) {
    uint8_t r = 0;
    for (int i = 0; i < 8; i++) r = uint8_t(r | ((b >> i) & 1) << (7 - i));
    return r;
}

// Interleaved, MSB-first raw DSD: frames * channels bytes.
Bytes rawDsd(size_t frames, uint32_t channels, uint32_t seed = 1) {
    Bytes out(frames * channels);
    uint32_t x = seed * 2654435761u + 1;
    for (auto& b : out) {
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        b = uint8_t(x);
    }
    return out;
}

void put(Bytes& out, std::string_view tag) {
    out.insert(out.end(), tag.begin(), tag.end());
}

template <typename T> void putLe(Bytes& out, T v) {
    for (size_t i = 0; i < sizeof(T); i++) out.push_back(uint8_t(uint64_t(v) >> (8 * i)));
}

template <typename T> void putBe(Bytes& out, T v) {
    for (size_t i = sizeof(T); i-- > 0;) out.push_back(uint8_t(uint64_t(v) >> (8 * i)));
}

void writeFile(const std::filesystem::path& path, const Bytes& bytes) {
    std::ofstream(path, std::ios::binary).write(reinterpret_cast<const char*>(bytes.data()), std::streamsize(bytes.size()));
}

struct DsfSpec {
    uint32_t channels = 2;
    uint32_t rate = kDsd64;
    uint32_t bitsPerSample = 1; // 1: LSB first, 8: MSB first
    int64_t sampleCountAdjust = 0;
    bool id3 = true;
};

// The final block is padded with nonzero bytes so that padding read as music is detected.
Bytes dsf(const Bytes& raw, const DsfSpec& s) {
    const size_t frames = raw.size() / s.channels;
    const size_t blocks = (frames + kBlock - 1) / kBlock;
    Bytes data(blocks * kBlock * s.channels, 0xA5);
    for (size_t i = 0; i < frames; i++)
        for (uint32_t c = 0; c < s.channels; c++) {
            const uint8_t b = raw[i * s.channels + c];
            data[(i / kBlock * s.channels + c) * kBlock + i % kBlock] = s.bitsPerSample == 1 ? reversed(b) : b;
        }
    const Bytes tag{'I', 'D', '3', 3, 0, 0, 0, 0, 0, 4, 'J', 'U', 'N', 'K'};
    const uint64_t dataChunk = 12 + data.size();
    const uint64_t total = 28 + 52 + dataChunk + (s.id3 ? tag.size() : 0);
    Bytes out;
    put(out, "DSD ");
    putLe<uint64_t>(out, 28);
    putLe<uint64_t>(out, total);
    putLe<uint64_t>(out, s.id3 ? 28 + 52 + dataChunk : 0);
    put(out, "fmt ");
    putLe<uint64_t>(out, 52);
    putLe<uint32_t>(out, 1);
    putLe<uint32_t>(out, 0);
    putLe<uint32_t>(out, s.channels == 1 ? 1 : 2);
    putLe<uint32_t>(out, s.channels);
    putLe<uint32_t>(out, s.rate);
    putLe<uint32_t>(out, s.bitsPerSample);
    putLe<uint64_t>(out, uint64_t(int64_t(frames * 8) + s.sampleCountAdjust));
    putLe<uint32_t>(out, uint32_t(kBlock));
    putLe<uint32_t>(out, 0);
    put(out, "data");
    putLe<uint64_t>(out, dataChunk);
    out.insert(out.end(), data.begin(), data.end());
    if (s.id3) out.insert(out.end(), tag.begin(), tag.end());
    return out;
}

void putChunk(Bytes& out, std::string_view id, const Bytes& body) {
    put(out, id);
    putBe<uint64_t>(out, body.size());
    out.insert(out.end(), body.begin(), body.end());
    if (body.size() % 2) out.push_back(0);
}

Bytes dffProp(uint32_t channels, uint32_t rate, bool dst) {
    Bytes fs, chnl, cmpr, prop;
    putBe<uint32_t>(fs, rate);
    putBe<uint16_t>(chnl, uint16_t(channels));
    for (uint32_t c = 0; c < channels; c++) put(chnl, channels == 1 ? "C   " : c == 0 ? "SLFT" : "SRGT");
    const std::string_view name = dst ? "DST Encoded" : "not compressed";
    put(cmpr, dst ? "DST " : "DSD ");
    cmpr.push_back(uint8_t(name.size()));
    put(cmpr, name);
    put(prop, "SND ");
    putChunk(prop, "FS  ", fs);
    putChunk(prop, "CHNL", chnl);
    putChunk(prop, "CMPR", cmpr);
    return prop;
}

Bytes dff(const Bytes& sound, uint32_t channels, uint32_t rate, bool dst) {
    Bytes form, fver;
    put(form, "DSD ");
    putBe<uint32_t>(fver, 0x01050000);
    putChunk(form, "FVER", fver);
    putChunk(form, "PROP", dffProp(channels, rate, dst));
    putChunk(form, dst ? "DST " : "DSD ", sound);
    Bytes out;
    putChunk(out, "FRM8", form);
    return out;
}

size_t dstFrameBytes(uint32_t channels, uint32_t rate) {
    return size_t(rate / 8 / 75) * channels;
}

// Uncoded DST frames carry the raw frame after one header byte (ISO/IEC 14496-3 subpart 10), so the raw input stays
// the reference. `header` replaces the frame header byte of every frame.
Bytes dstSound(const Bytes& raw, uint32_t channels, uint32_t rate, bool crc, uint8_t header = 0, size_t trim = 0) {
    const size_t frameBytes = dstFrameBytes(channels, rate);
    const auto count = uint32_t(raw.size() / frameBytes);
    Bytes sound, frte;
    putBe<uint32_t>(frte, count);
    putBe<uint16_t>(frte, 75);
    putChunk(sound, "FRTE", frte);
    for (uint32_t f = 0; f < count; f++) {
        Bytes frame{header};
        frame.insert(frame.end(), raw.begin() + ptrdiff_t(f * frameBytes), raw.begin() + ptrdiff_t((f + 1) * frameBytes - trim));
        putChunk(sound, "DSTF", frame);
        if (crc) putChunk(sound, "DSTC", Bytes{0, 0, 0, 0});
    }
    return sound;
}

std::filesystem::path fixture(const std::filesystem::path& name, const Bytes& bytes) {
    const auto path = testutil::tempDir() / name;
    writeFile(path, bytes);
    return path;
}

Bytes readAll(DsdReader& r, size_t chunk = 1000) {
    Bytes out;
    Bytes buf(chunk * r.info().channels);
    while (const size_t n = r.read(buf.data(), chunk))
        out.insert(out.end(), buf.begin(), buf.begin() + ptrdiff_t(n * r.info().channels));
    return out;
}

void expectSeeks(DsdReader& r, const Bytes& raw) {
    const uint32_t ch = r.info().channels;
    const uint64_t frames = r.info().frames;
    for (const uint64_t at : {uint64_t(0), uint64_t(1), uint64_t(kBlock - 1), uint64_t(kBlock), uint64_t(kBlock + 17), frames / 2,
                              frames - 3, frames}) {
        r.seek(at);
        Bytes got(size_t(64) * ch);
        const size_t n = r.read(got.data(), 64);
        ASSERT_EQ(n, std::min<uint64_t>(64, frames - at)) << "seek " << at;
        EXPECT_TRUE(std::equal(got.begin(), got.begin() + ptrdiff_t(n * ch), raw.begin() + ptrdiff_t(at * ch))) << "seek " << at;
    }
    EXPECT_THROW(r.seek(frames + 1), Error);
}

ErrorCode errorOf(const std::function<void()>& f) {
    try {
        f();
    } catch (const Error& e) {
        return e.code();
    }
    ADD_FAILURE() << "no error";
    return ErrorCode::Other;
}

} // namespace

TEST(DsdReaderTest, DsfBlockInterleavedLsbFirstMatchesRawWithoutPadding) {
    const Bytes raw = rawDsd(3 * kBlock + 1000, 2);
    auto r = openDsdReader(fixture("dsd-dsf64.dsf", dsf(raw, {})));
    EXPECT_EQ(r->info().channels, 2u);
    EXPECT_EQ(r->info().sampleRate, kDsd64);
    EXPECT_EQ(r->info().frames, 3 * kBlock + 1000);
    EXPECT_FALSE(r->info().dst);
    EXPECT_TRUE(readAll(*r) == raw);
    expectSeeks(*r, raw);
}

TEST(DsdReaderTest, DsfMsbFirstEightBitFile) {
    const Bytes raw = rawDsd(kBlock + 77, 2, 2);
    auto r = openDsdReader(fixture("dsd-dsf-msb.dsf", dsf(raw, {.bitsPerSample = 8})));
    EXPECT_TRUE(readAll(*r) == raw);
}

TEST(DsdReaderTest, DsfValidBitCountDropsPartialFinalByte) {
    const Bytes raw = rawDsd(kBlock + 10, 2, 3);
    auto r = openDsdReader(fixture("dsd-dsf-validbits.dsf", dsf(raw, {.sampleCountAdjust = -3})));
    EXPECT_EQ(r->info().frames, kBlock + 9);
    EXPECT_TRUE(readAll(*r) == Bytes(raw.begin(), raw.end() - 2));
}

TEST(DsdReaderTest, DsfMonoAndDsd256) {
    const Bytes raw = rawDsd(2 * kBlock + 5, 1, 4);
    auto r = openDsdReader(fixture("dsd-dsf256-mono.dsf", dsf(raw, {.channels = 1, .rate = 4 * kDsd64, .id3 = false})));
    EXPECT_EQ(r->info().channels, 1u);
    EXPECT_EQ(r->info().sampleRate, 4 * kDsd64);
    EXPECT_TRUE(readAll(*r) == raw);
}

TEST(DsdReaderTest, DffByteInterleavedMatchesRaw) {
    const Bytes raw = rawDsd(3 * kBlock + 333, 2, 5);
    auto r = openDsdReader(fixture("dsd-dff128.dff", dff(raw, 2, 2 * kDsd64, false)));
    EXPECT_EQ(r->info().sampleRate, 2 * kDsd64);
    EXPECT_EQ(r->info().frames, 3 * kBlock + 333);
    EXPECT_TRUE(readAll(*r) == raw);
    expectSeeks(*r, raw);
}

TEST(DsdReaderTest, DffOddSizedSoundChunkIsPadded) {
    const Bytes raw = rawDsd(kBlock + 1, 1, 6);
    auto r = openDsdReader(fixture("dsd-dff-odd.dff", dff(raw, 1, kDsd64, false)));
    EXPECT_EQ(r->info().frames, kBlock + 1);
    EXPECT_TRUE(readAll(*r) == raw);
}

TEST(DsdReaderTest, DstStaysDisabledUnlessAllowed) {
    const Bytes raw = rawDsd(3 * dstFrameBytes(1, kDsd64), 2, 7);
    const auto path = fixture("dsd-dst-gated.dff", dff(dstSound(raw, 2, kDsd64, false), 2, kDsd64, true));
    EXPECT_EQ(errorOf([&] { openDsdReader(path); }), ErrorCode::UnsupportedStream);
}

TEST(DsdReaderTest, DstUncodedFramesMatchRaw) {
    for (const bool crc : {false, true}) {
        const Bytes raw = rawDsd(4 * dstFrameBytes(1, kDsd64), 2, 8);
        auto r = openDsdReader(fixture("dsd-dst-uncoded.dff", dff(dstSound(raw, 2, kDsd64, crc), 2, kDsd64, true)), true);
        EXPECT_TRUE(r->info().dst);
        EXPECT_EQ(r->info().frames, 4 * dstFrameBytes(1, kDsd64));
        EXPECT_TRUE(readAll(*r, 777) == raw) << "crc " << crc;
        expectSeeks(*r, raw);
    }
}

TEST(DsdReaderTest, MalformedDstFramesFail) {
    const Bytes raw = rawDsd(2 * dstFrameBytes(1, kDsd64), 2, 9);
    const auto reads = [&](const char* name, const Bytes& sound) {
        return errorOf([&] {
            auto r = openDsdReader(fixture(name, dff(sound, 2, kDsd64, true)), true);
            readAll(*r);
        });
    };
    EXPECT_EQ(reads("dsd-dst-reserved.dff", dstSound(raw, 2, kDsd64, false, 0x01)), ErrorCode::DecodeFailed);
    EXPECT_EQ(reads("dsd-dst-short.dff", dstSound(raw, 2, kDsd64, false, 0x00, 10)), ErrorCode::DecodeFailed);
    Bytes empty, frte;
    putBe<uint32_t>(frte, 1);
    putBe<uint16_t>(frte, 75);
    putChunk(empty, "FRTE", frte);
    putChunk(empty, "DSTF", Bytes{0x80});
    EXPECT_EQ(reads("dsd-dst-tiny.dff", empty), ErrorCode::DecodeFailed);
}

TEST(DsdReaderTest, TruncatedFilesFail) {
    for (const auto& [name, bytes] :
         {std::pair{std::string("dsd-trunc.dsf"), dsf(rawDsd(4 * kBlock, 2, 10), {.id3 = false})},
          std::pair{std::string("dsd-trunc.dff"), dff(rawDsd(4 * kBlock, 2, 10), 2, kDsd64, false)}}) {
        const auto path = fixture(name, Bytes(bytes.begin(), bytes.begin() + ptrdiff_t(bytes.size() * 3 / 5)));
        EXPECT_EQ(errorOf([&] {
                      auto r = openDsdReader(path);
                      readAll(*r);
                  }),
                  ErrorCode::DecodeFailed)
            << name;
    }
}

TEST(DsdReaderTest, RejectsOtherFilesAndOpensUnicodePaths) {
    EXPECT_EQ(errorOf([] { openDsdReader(testutil::tempDir() / "dsd-missing.dsf"); }), ErrorCode::FileOpen);
    EXPECT_EQ(errorOf([] { openDsdReader(testutil::testFile("16-44.1k")); }), ErrorCode::UnsupportedStream);
    const Bytes raw = rawDsd(100, 2, 11);
    auto r = openDsdReader(fixture(std::filesystem::path(u8"dsd-音樂.dsf"), dsf(raw, {})));
    EXPECT_TRUE(readAll(*r) == raw);
}

// Local real DSF files (testdata/, not in Git), compared with an independent block de-interleave of the file bytes.
TEST(DsdReaderTest, RealDsfMatchesIndependentParse) {
    std::filesystem::path testdata;
    for (auto d = std::filesystem::current_path(); !d.empty() && d != d.root_path(); d = d.parent_path())
        if (std::filesystem::exists(d / "testdata")) {
            testdata = d / "testdata";
            break;
        }
    if (testdata.empty()) GTEST_SKIP() << "testdata/ not present";
    int compared = 0;
    for (const auto& entry : std::filesystem::directory_iterator(testdata)) {
        if (entry.path().extension() != ".dsf") continue;
        std::ifstream in(entry.path(), std::ios::binary);
        Bytes header(92);
        in.read(reinterpret_cast<char*>(header.data()), std::streamsize(header.size()));
        const auto le = [&](size_t at, size_t n) {
            uint64_t v = 0;
            for (size_t i = 0; i < n; i++) v |= uint64_t(header[at + i]) << (8 * i);
            return v;
        };
        const auto channels = uint32_t(le(52, 4));
        const bool lsbFirst = le(60, 4) == 1;
        const uint64_t frames = le(64, 8) / 8;
        auto r = openDsdReader(entry.path());
        ASSERT_EQ(r->info().channels, channels);
        ASSERT_EQ(r->info().sampleRate, uint32_t(le(56, 4)));
        ASSERT_EQ(r->info().frames, frames) << entry.path();
        Bytes group(kBlock * channels), expected(kBlock * channels), got(kBlock * channels);
        for (uint64_t at = 0; at < frames; at += kBlock) {
            in.read(reinterpret_cast<char*>(group.data()), std::streamsize(group.size()));
            const auto n = size_t(std::min<uint64_t>(kBlock, frames - at));
            for (size_t i = 0; i < n; i++)
                for (uint32_t c = 0; c < channels; c++) {
                    const uint8_t b = group[c * kBlock + i];
                    expected[i * channels + c] = lsbFirst ? reversed(b) : b;
                }
            ASSERT_EQ(r->read(got.data(), n), n);
            ASSERT_TRUE(std::equal(got.begin(), got.begin() + ptrdiff_t(n * channels), expected.begin()))
                << entry.path() << " frame " << at;
        }
        EXPECT_EQ(r->read(got.data(), 1), 0u);
        compared++;
    }
    if (!compared) GTEST_SKIP() << "no DSF samples in testdata/";
}
